.ovn-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ovn-root,.ovn-root *,.ovn-root *::before,.ovn-root *::after{box-sizing:border-box}
.ovn-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ovn-root img{display:block;border:0;max-width:none}
.ovn-root > [data-node-id]{will-change:transform}
.ovn-root [hidden]{display:none!important}
.ovn-root [data-sh-theme="light"]{display:none!important}
.ovn-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.ovn-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.ovn-root .n22_1333{align-content:stretch;display:flex;align-items:center;position:relative;flex-shrink:0;width:100px;height:24px}
.ovn-root .n22_1333::after{content:"";position:absolute;inset:-0px;border:1px solid color-mix(in srgb, var(--wa-point, rgb(0 183 238)) 50%, transparent);border-radius:inherit;pointer-events:none}
.ovn-root .x14{position:absolute;background-color:color-mix(in srgb, var(--wa-surface, rgb(1 13 53)) 50%, transparent);inset:0;pointer-events:none}
.ovn-root .n22_1334{background-color:color-mix(in srgb, var(--wa-point, rgb(209 234 255)) 10%, transparent);align-content:stretch;display:flex;flex-direction:column;height:22px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:40px;border-style:solid;border-color:color-mix(in srgb, var(--wa-point, rgb(0 183 238)) 10%, transparent);border-width:0px}
.ovn-root .n22_1335{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:21px;height:8px}
.ovn-root .n22_1336{align-content:stretch;display:flex;flex:1 0 0;height:22px;align-items:center;justify-content:flex-end;min-width:1px;padding:10px;position:relative}
.ovn-root .n22_1337{word-break:break-word;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:500;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;text-align:right;color:var(--wa-text, #fff);white-space:nowrap;width:24px}
.ovn-root .x15{position:absolute;inset:0;pointer-events:none;border-radius:inherit;box-shadow:inset 0px 0px 16px 0px rgba(31,94,144,0.65)}
.ovn-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.ovn-root[data-theme="light"] [data-name="Badge/Critical"] p,.ovn-root[data-theme="light"] [data-name^="status-critical"] p,.ovn-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.ovn-root[data-theme="light"] [data-name="Badge/Major"] p,.ovn-root[data-theme="light"] [data-name^="status-major"] p,.ovn-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.ovn-root[data-theme="light"] [data-name="Badge/Minor"] p,.ovn-root[data-theme="light"] [data-name^="status-minor"] p,.ovn-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.ovn-root[data-theme="light"] [data-name="Badge/Warning"] p,.ovn-root[data-theme="light"] [data-name^="status-warning"] p,.ovn-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.ovn-root[data-theme="light"] [data-name="Badge/Normal"] p,.ovn-root[data-theme="light"] [data-name^="status-normal"] p,.ovn-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.ovn-root[data-theme="light"] [data-name="Button/Ack"] p,.ovn-root[data-theme="light"] [data-name="Button/Ack All"] p,.ovn-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.ovn-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.ovn-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.ovn-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.ovn-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.ovn-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.ovn-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.ovn-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.ovn-root[data-theme="light"] :is([data-name="Symbol"],[data-name="Floor"],[data-name="Floor Layer"],[data-name="Effect"]) img{filter:brightness(1.75) saturate(.55);opacity:.7}
.ovn-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.ovn-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.ovn-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1e86f0)!important}
.ovn-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.ovn-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.ovn-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.ovn-root[data-theme="light"] :is([data-name^="Node/"],[data-name="Icons"],[data-name="Node Group"]) p{text-shadow:0 0 3px #fff,0 0 6px #fff,0 0 10px rgba(255,255,255,.9)}
.ovn-root[data-theme="light"] .x14{background-color:color-mix(in srgb, var(--wa-bg, rgb(238 240 246)) 50%, transparent)}
.ovn-root[data-theme="light"] .n22_1335{color:var(--wa-point, #0f2238)}
.ovn-root[data-theme="light"] .n22_1337{color:var(--wa-point, #0f2238)}
